import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"kiwa v1.24 released — Edge / Serverless 深化 (advanced edge semantics 8 axis + 3 dogfood edge app)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.24/gh-discussions-announcement.md","filePath":"announcements/v1.24/gh-discussions-announcement.md"}'),d={name:"announcements/v1.24/gh-discussions-announcement.md"};function r(i,e,n,c,l,g){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="kiwa-v1-24-released-—-edge-serverless-深化-advanced-edge-semantics-8-axis-3-dogfood-edge-app" tabindex="-1">kiwa v1.24 released — Edge / Serverless 深化 (advanced edge semantics 8 axis + 3 dogfood edge app) <a class="header-anchor" href="#kiwa-v1-24-released-—-edge-serverless-深化-advanced-edge-semantics-8-axis-3-dogfood-edge-app" aria-label="Permalink to &quot;kiwa v1.24 released — Edge / Serverless 深化 (advanced edge semantics 8 axis + 3 dogfood edge app)&quot;">​</a></h1><p>v1.24 is out. After v1.14&#39;s <code>@kiwa-test/edge</code> v0.1 landed the fetch handler + KV / R2 / D1 / DurableObject minimal mocks baseline, v1.24 layers <strong>8 axes of advanced edge semantics</strong> on top — Durable Object hibernation + WebSocket edge + edge KV eventual consistency + geo-replicated + Cron trigger + subrequest limit + CPU time limit + streaming Response. Platform-neutral state machines + strict transition guards + fidelity harness across all 3 platforms (Cloudflare Workers + Vercel Edge + Deno Deploy). 120 new semantics behavior tests + 3 dogfood edge apps + 3 tutorials + concept doc SSOT.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-test/edge</code> v1.1.0</strong> (8-axis advanced edge semantics). v0.1&#39;s fetch handler + minimal binding mocks (<code>invokeEdgeHandler</code> / <code>createKvNamespace</code> / <code>EdgeFetchHandler</code> / <code>EdgeEnvBindings</code> / <code>SimulatedExecutionContext</code>) keep every prior signature. v1.1 lands <code>packages/edge/src/semantics/*</code> — 1 axis = 1 file of pure state-machine helpers that operate on a shared <code>EdgePlatform</code> union (<code>&#39;cloudflare&#39; | &#39;vercel&#39; | &#39;deno&#39;</code>). Every axis emits a strongly typed <code>AxisStep</code> sequence so tests assert on the transitions, not the platform-specific event names. <ul><li><code>durable-object.ts</code> — Cloudflare Hibernation API envelope (<code>initialized</code> → <code>active</code> on request / alarm / storage-write, transactional storage guarantee)</li><li><code>websocket-edge.ts</code> — edge WebSocket lifecycle (<code>pending</code> → <code>open</code> → <code>closed</code>, sendMessage rejects unless <code>open</code>)</li><li><code>edge-kv.ts</code> — read-through cache with consistency envelope (<code>consistent</code> for Deno KV primary, <code>eventually-consistent</code> for Cloudflare KV / Vercel Edge Config / Deno KV replicas, cold read / cache-hit / cache-miss / range query)</li><li><code>geo-replicated.ts</code> — primary-write / replica-lag / sync / conflict-resolve (<code>in-sync</code> → <code>lagging</code> → <code>in-sync</code> iff every replica lag returns to 0, or <code>conflict-detected</code> → <code>in-sync</code> on resolveConflict)</li><li><code>cron-trigger.ts</code> — scheduled + queue + email 3-source trigger with retry policy (<code>scheduled</code> → <code>running</code> → <code>completed</code> or <code>failed</code>, retry backoff exponent)</li><li><code>subrequest-limit.ts</code> — fetch quota + iteration + warning threshold + hard limit (<code>open</code> → <code>warning</code> → <code>blocked</code>)</li><li><code>cpu-time-limit.ts</code> — budget tracking + warning + throttle (<code>open</code> → <code>warning</code> → <code>throttled</code> → <code>exhausted</code>)</li><li><code>streaming-response.ts</code> — chunked + SSE + WebSocket streaming + backpressure resume (<code>open</code> → <code>chunking</code> → <code>paused</code> → <code>chunking</code> → <code>closed</code>)</li></ul></li><li><strong><code>examples/dogfood-cloudflare-workers-durable-object-app</code></strong> — Cloudflare Workers Durable Object realtime chat app with Hibernation API + transactional storage + WebSocket edge broadcast. 40 vitest exercising room-per-DO state + alarm-driven message purge + 2-user broadcast fidelity. <code>KIWA_MODE=real</code> flips the same tests to hit real Miniflare without touching bodies.</li><li><strong><code>examples/dogfood-vercel-edge-function-app</code></strong> — Next.js 15 middleware + edge runtime + Vercel KV (Redis) + streaming Response (SSE) + geo-based routing (accept-language + geo IP → region) + edge cache invalidation. 45 vitest — the widest v1.24 dogfood app for edge because SSE streaming + geo routing double as backpressure + region-failover signal sources.</li><li><strong><code>examples/dogfood-deno-deploy-geo-app</code></strong> — Fresh + Deno KV geo-replicated with strong consistency + Deno Deploy Cron + queue trigger + read-your-writes. 50 vitest exercising multi-region KV write + eventual consistency observation + cron trigger fire + queue trigger dispatch. <code>KIWA_MODE=real</code> opts into the real Deno Deploy sandbox.</li><li><strong>docs</strong> — 3 new tutorials (42 Cloudflare Durable Object + 43 Vercel Edge streaming + 44 Deno Deploy geo) + concept doc <code>edge-runtime-testing.md</code> — SSOT for the 8 axes + platform-specific fidelity surface across all 3 dogfood edge apps. Migration guide v1.23 → v1.24 (additive-only). Snippet validation test <code>packages/edge/tests/docs-tutorial-v1.24.test.ts</code> (16 tests) re-runs every code snippet against the real <code>@kiwa-test/edge</code> API. Same drift-detection pattern as <code>docs-tutorial-v1.21.test.ts</code> + <code>docs-tutorial-v1.22.test.ts</code> + <code>docs-tutorial-v1.23.test.ts</code>. VitePress sidebar gains an <code>Edge / Serverless 深化 (v1.24)</code> tutorial section; gh-pages published via <code>/docs-publish-kiwa</code>.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#914-#919)</li><li><strong>6 PRs merged</strong> (v1.24-1 + v1.24-2 + v1.24-3 + v1.24-4 + v1.24-5 + this publish PR)</li><li><strong>1 npm minor bump</strong> (<code>@kiwa-test/edge</code> v1.0.2 → v1.1.0) — kiwa runtime fixture count stays 34</li><li><strong>3 new dogfood edge apps</strong> with fidelity reports feeding the 7-axis release gate</li><li><strong>~271 new tests</strong> across 8 semantics axes (120) + Cloudflare (40) + Vercel (45) + Deno (50) + snippet validation (16)</li></ul><h2 id="why-8-axes-and-not-just-fetch-handler-mock" tabindex="-1">Why 8 axes (and not just fetch handler mock) <a class="header-anchor" href="#why-8-axes-and-not-just-fetch-handler-mock" aria-label="Permalink to &quot;Why 8 axes (and not just fetch handler mock)&quot;">​</a></h2><p>Edge testing has three failure modes that a <code>fetch</code>-only mock can&#39;t catch, no matter how many mock KV / R2 stubs you pack in.</p><ul><li><strong>Stateful drift</strong> — a Durable Object&#39;s real lifecycle isn&#39;t <code>create → serve</code>; it&#39;s a 4-event trace (<code>created</code> / <code>requested</code> / <code>alarm-fired</code> / <code>storage-written</code>) with transactional storage + Hibernation-driven wake-up. Tests that assert <code>Response.status === 200</code> miss the state-machine drift, and production bugs surface as lost storage writes or duplicate broadcasts.</li><li><strong>Consistency envelope</strong> — real edge KV trades strong consistency for low-latency edge reads (Cloudflare KV, Vercel Edge Config, Deno KV replicas). Tests that skip the primary-vs-replica distinction miss read-your-writes bugs and let apps ship with stale-read races.</li><li><strong>Cross-platform fidelity</strong> — Cloudflare fires cron from 3 sources (scheduled + queue + email); Vercel exposes only scheduled + queue; Deno Deploy exposes scheduled + queue. Streaming Response backpressure is measured in bytes on Vercel, chunks on Cloudflare. A neutral test surface makes these differences <strong>explicit assertions</strong>, not silent regressions.</li></ul><p>The 8 axes are the smallest set that reproduces the full edge envelope across the 3 target platforms. Each axis is an independent module under <code>@kiwa-test/edge/semantics/*</code>; each provides pure functions that operate on a session object + emit a strongly typed <code>AxisStep</code> sequence so tests can assert on transitions, not event shapes.</p><h2 id="_3-dogfood-edge-apps-—-one-adapter-surface-three-edge-envelopes" tabindex="-1">3 dogfood edge apps — one adapter surface, three edge envelopes <a class="header-anchor" href="#_3-dogfood-edge-apps-—-one-adapter-surface-three-edge-envelopes" aria-label="Permalink to &quot;3 dogfood edge apps — one adapter surface, three edge envelopes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>App</th><th>Framework</th><th>Distinguishing axes</th></tr></thead><tbody><tr><td><code>dogfood-cloudflare-workers-durable-object-app</code></td><td>Cloudflare Workers</td><td>Durable Object + Hibernation API + storage transactional + WebSocket edge broadcast + alarm purge</td></tr><tr><td><code>dogfood-vercel-edge-function-app</code></td><td>Next.js 15 middleware + edge runtime</td><td>Vercel KV Redis + streaming Response SSE + geo-based routing + edge cache invalidation</td></tr><tr><td><code>dogfood-deno-deploy-geo-app</code></td><td>Fresh + Deno Deploy</td><td>Deno KV geo-replicated + Deno Deploy Cron + queue trigger + read-your-writes + multi-region write</td></tr></tbody></table><p>All three share the same <code>KIWA_MODE=mock|real-optional|real</code> switch v1.22 established — mock branch runs in ~1 ms per test; <code>KIWA_MODE=real</code> flips to the actual platform sandbox without touching bodies.</p><h2 id="_14-milestone-streak" tabindex="-1">14-milestone streak <a class="header-anchor" href="#_14-milestone-streak" aria-label="Permalink to &quot;14-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → v1.18 (Blockchain depth) → v1.19 (Framework 深化) → v1.20 (Streaming 深化) → v1.21 (Auth 深化) → v1.22 (Auth 深化 II) → v1.23 (Payment 深化) → <strong>v1.24 (Edge / Serverless 深化)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100% milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li><li>IoT depth (MQTT / CoAP / LWM2M)</li><li>DB depth (SurrealDB / EdgeDB / Turso)</li><li>Edge / Serverless 深化 II — real driver layer (real Miniflare + wrangler dev + Vercel Edge sandbox + Deno Deploy sandbox testcontainers + <code>KIWA_MODE=real-required</code> nightly)</li></ul><p>Feedback welcome on which of these should land next.</p>',18)])])}const h=o(d,[["render",r]]);export{p as __pageData,h as default};
